BOOL __stdcall HandleUpdateToExpansion(D2ControlMsg * pControlMsg) {
    uint32_t bUpgradeOk;
    int32_t nJoinResult;
    uint16_t* pwszMessage;
    uint16_t* pwszFormat;
    uint16_t awszCharName[256];
    uint8_t aszCommandAnsi[256];
    D2CharSelStrc* pSelectedCharacter;
    char* pwszCommandString;
    BOOL bIsExpansion = Fog::D2CheckExpansionGame();
    if (!bIsExpansion) {
      return 1;
    }

    int nCharIndex = 0;
    for (pSelectedCharacter = D2Client::CharScreen::D2CharSelStrcFirst; pSelectedCharacter; pSelectedCharacter = pSelectedCharacter->pNext) {
      uint16_t awszFormattedMsg[256];
      if (D2Client::CharScreen::nSelectedCharIndex == nCharIndex) {
        if (!pSelectedCharacter) {
          break;
        }
        if (pSelectedCharacter->nCharacterFlags & 0x20) {
          return 1;
        }

        pwszCommandString = pSelectedCharacter->szCommandStringTable;
        if (!pwszCommandString || !*(short int*)pwszCommandString) {
          bIsExpansion = UpdateSaveFileToExpansion(pSelectedCharacter->szCharname);
          if (!bIsExpansion) {
            nJoinResult = 1;
            pwszMessage = D2Lang::StrTable::strtable::GetLocaleString(0x5570);
            MainMenus::UIMENU_AnotherSmallPopupWithContentAndSomeKindofTypeSelection(pwszMessage, UIMENU_CharacterSelectAllGameTypes, nJoinResult);
            break;
          }
        } else {
          D2Lang::Unicode::UNISYS::UNICODE_WideToMultiByte((char*)aszCommandAnsi, (uint16_t*)pwszCommandString, 0xff);
          bUpgradeOk = MainMenus::MAINMENU_UpgradeCharacterToExpansion(pSelectedCharacter, aszCommandAnsi);
          if (!bUpgradeOk) {
            nJoinResult = D2MCPClient::McpConnect::GetD2GSJoinResult();
            if (nJoinResult == 0x7b) {
              Fog::File::CONTAINER_InitializeBuffer(awszFormattedMsg, 2, 0x100, MainMenus::STRING_ZeroOneWCHAR);
              Fog::File::CONTAINER_InitializeBuffer(awszCharName, 2, 0x100, MainMenus::STRING_ZeroOneWCHAR);
              D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(awszCharName, pSelectedCharacter->szCharname, 0x100);
              pwszMessage = awszCharName;
              pwszFormat = D2Lang::StrTable::strtable::GetLocaleString(0x2b89);
              D2Lang::Unicode::UNISYS::UNICODE_FormatWideString(0x100, awszFormattedMsg, pwszFormat, (uint16_t*)pwszMessage);
              pwszMessage = awszFormattedMsg;
            } else {
              pwszMessage = D2Lang::StrTable::strtable::GetLocaleString(0x145b);
            }

            MainMenus::MAINMENU_ShowPopupWithCancel(pwszMessage, UIMENU_CharacterSelectAllGameTypes);
            gbCharSelectInProgress = 0;
            return 1;
          }
        }

        pSelectedCharacter->nCharacterFlags |= 0x20;
        CharSel::DRAW_LocalCharsInSelectionScreen0();
        MainMenus::FORMS_DestroyList();
        break;
      }

      nCharIndex++;
    }

    D2Win::Src::D2WinMain::D2WINMAIN_SetControlVisible(&gpCharSelScreenControl->sControl, 0);
    return 1;
}

BOOL __stdcall LAUNCHER_StartGameWithSelectedCharacter(D2ControlMsg * pControlMsg) {
    uint16_t* pwszErrorMsg;
    uint8_t aszCommandAnsi[256];
    int nCharIndex = 0;
    D2CharSelStrc* pCharSel = D2Client::CharScreen::D2CharSelStrcFirst;
    while (true) {
      if (!pCharSel) {
        return 0;
      }
      if (D2Client::CharScreen::nSelectedCharIndex == nCharIndex) {
        break;
      }

      pCharSel = pCharSel->pNext;
      nCharIndex++;
    }

    if (!pCharSel) {
      return 0;
    }

    char* pbCommandAnsi = pCharSel->szCommandStringTable;
    gbCharSelectInProgress = 1;
    if (!pbCommandAnsi || !*(short int*)pbCommandAnsi) {
      pbCommandAnsi = "";
    } else {
      BOOL BVar1;
      D2Lang::Unicode::UNISYS::UNICODE_WideToMultiByte((char*)aszCommandAnsi, (uint16_t*)pbCommandAnsi, 0xff);
      BVar1 = MainMenus::MAINMENU_DeleteCharacterOnRealm(pCharSel, aszCommandAnsi);
      if (!BVar1) {
        pwszErrorMsg = D2Lang::StrTable::strtable::GetLocaleString(0x145b);
        MainMenus::MAINMENU_ShowPopupWithCancel(pwszErrorMsg, UIMENU_CharacterSelectAllGameTypes);
        gbCharSelectInProgress = 0;
        return 1;
      }

      gnCharSelCreateNewButtonClickCount++;
      gnCharSelLoadedCharCount = 0;
      pbCommandAnsi = (char*)aszCommandAnsi;
    }

    LAUNCHER_DeleteCharacterFiles(pCharSel, pbCommandAnsi);
    UIMENU_CharacterSelectAllGameTypes();
    gbCharSelectInProgress = 0;
    return 1;
}

void __fastcall LAUNCHER_InitNetworkLobbyQueue(D2IniConfigStrc * pIniConfig) {
    if (pIniConfig->pBNetClientCallbacks) {
      return;
    }

    gpBNetCallbacks = Bnclient::NET_InitAndGetLobbyChatQueue();
    if (!gpBNetCallbacks) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x94);
      exit(-1);
    }

    pIniConfig->pBNetClientCallbacks = gpBNetCallbacks;
    gpBNetCallbacks->pfnSetLoggingFlag((uint32_t)pIniConfig);
}

