int __stdcall LAUNCHER_HandleBnetConnect_1(int nFrameIndex) {
    uint32_t dwResponseCtx;
    BOOL bIsConnected = gpBNetCallbacks->pfnWaitForCreateAccountResponse(&dwResponseCtx);
    if (bIsConnected) {
      D2Win::Src::D2WinMain::D2WINMAIN_ClearMessageLoopFlag();
    }
    if (!gnBusyFlag) {
      bIsConnected = gpBNetCallbacks->pfnIsSocketConnected();
      if (bIsConnected) {
        bIsConnected = MainMenus::MAINMENU_GetGlobalValue2();
        if (!bIsConnected) {
          return 1;
        }
      }
    }

    gpBNetCallbacks->pfnDisconnect();
    D2Win::Src::D2WinMain::D2WINMAIN_ClearMessageLoopFlag();
    return 1;
}

